    const result = calculateDiscount(price, testCase.quantity);
    const pass = Math.abs(result - testCase.expected) < 1; // Check for floating point tolerance

    if (pass) {
        console.log(`PASS: quantity: ${testCase.quantity}, price: ${price}`);
