		// Parse Age (as of July 1, 2025)
		person.Age = calculateAge(*birthTime)

		// Parse Gender (optional, may not exist in some files)
		if len(record) > 3 {
			person.Gender = record[3]
		}

		persons = append(persons, person)
	}

	return persons, nil
}

