	"encoding/json"
	"os"
	"strconv"
)

type Person struct {
	Name  string  `json:"name"`
	Age   int     `json:"age"`
	Email string  `json:"email"`
	Score float64 `json:"score"`
}

func main() {
	file, err := os.Open("input/data.csv")
	if err != nil {
		os.Exit(1)
	}
	defer file.Close()

