        (49, 10.0, "Quantity 49 (10-49, 10% off)", 441.0),
        (50, 10.0, "Quantity 50 (>= 50, 25% off)", 375.0),
    ]

    for qty, price, desc, expected in test_cases:
        result = calculate_discount(price, qty)
